  ('Xihu Longjing', 'xihu-longjing', '', '龍井', 'Longjing, also known as Dragon Well, is a famous Chinese green tea from Hangzhou, Zhejiang. Renowned for its flat emerald leaves, gentle chestnut aroma, and smooth, sweet flavor, it represents the elegance and purity of traditional Chinese tea craftsmanship.', 'Hangzhou, Zhejiang, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Emei Zhu Ye Qing', 'emei-zhu-ye-qing', '', '竹叶青', 'Emei Zhu Ye Qing is a renowned green tea from Mount Emei in Sichuan, China. Handcrafted from tender spring buds, it offers a bright jade liquor, fresh orchid aroma, and clean, sweet vegetal taste with lingering umami purity.', 'Emeishan, Sichuan, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Dong Ting Bi Luo Chun', 'dong-ting-bi-luo-chun', '', '碧螺春', 'Bi Luo Chun, or “Jade Snail Spring,” is a famous green tea from Dongting Mountain in Jiangsu. Its tightly curled buds release a vibrant floral-fruity aroma, delicate sweetness, and refreshing, lingering aftertaste full of vitality.', 'Jiangsu, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Gu Zhang Mao Jian', 'gu-zhang-mao-jian', '', '古丈毛尖', 'Gu Zhang Mao Jian is a refined Chinese green tea from Guzhang area, Hunan province, known for its slender, needle-like leaves covered with fine down.', 'Guzhang, Hunan, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Anhua Song Zhen', 'anhua-song-zhen', '', '安化松针', 'Anhua Song Zhen is a refined green tea from Anhua County, Hunan. Crafted from tender buds, it offers a bright green infusion, fresh pine-like aroma, and smooth, sweet taste with a clean, lasting finish.', 'Anhua, Hunan, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Hunan Zao Chun Yun Wu', 'hunan-zao-chun-yun-wu', '', '早春云雾', 'Hunan Jiu Yi Zao Chun Yun Wu is an early spring green tea from Jiuyi Mountain, Hunan. Grown in misty highlands, it reveals a fresh vegetal aroma, smooth texture, and gentle sweetness balanced by subtle mountain briskness.', 'Jiu Yi, Hunan, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Gao Shan Dian Lu', 'gao-shan-dian-lu', '', '高山滇绿', 'Gao Shan Dian Lu is a high-mountain green tea from Yunnan. Grown in misty elevations, it reveals a bright jade liquor, gentle floral aroma, and balanced sweetness with a fresh, lingering mountain aftertaste.', 'Yunnan, China', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
  ('Saejak', 'saejak', '', '세작', 'Saejak is an early spring Korean green tea made from tender young leaves. It offers a bright, clear liquor, gentle sea breeze aroma, and smooth, sweet taste with delicate umami and fresh vegetal notes.', 'South Korea', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 150ml at 75–80°C. Steep 1–2 minutes; re-steep up to 3 times.', ARRAY[]::text[], ARRAY[]::text[], '#7BA05B', NULL, NULL, NULL, NULL, 'default', 'Teapp', NULL, TRUE),
